/**
 * `buy verify hosted` — prove humanity against a gateway that hosts the Self
 * receiver, so this machine hosts nothing (celo-org/cpay#63).
 *
 * The difference from `verify serve` is where the Self app POSTs the proof.
 * There, it POSTs to this machine, which is why that command has to stand up a
 * public HTTPS endpoint and therefore why `cloudflared` was a prerequisite for
 * buying anything on a KYC-gated route. Here it POSTs to the gateway, and this
 * command only mints a session, shows a QR, waits, and collects the result.
 *
 * That also fixes what the tunnel broke. Self derives a proof's scope as
 * hashEndpointWithScope(endpoint, scope), so a per-session tunnel URL yields a
 * ROTATING nullifier and the per-human caps key on something the caller can
 * change at will. A gateway-hosted endpoint is stable, so those caps mean
 * something for the first time.
 */
import { type MintedSession, type SoftKycRequirements } from '@celo/buy-identity';
import { type VerifyOpts } from './verify-request.js';
export type VerifyHostedOpts = VerifyOpts & {
    readonly timeoutSeconds?: string;
    readonly pollSeconds?: string;
};
export declare function requirementsFrom(minted: MintedSession): SoftKycRequirements;
export declare function verifyHostedCommand(opts: VerifyHostedOpts): Promise<void>;
